package odc;
import java.util.*;
import static odc.PhysicalTopology.Type.*;
import static odc.LogicalLinks.Kind.*;
public final class NetworkAdmissionTest {
 static int checks;
 static void yes(boolean b,String message){checks++;if(!b)throw new AssertionError(message);}
 static void eq(double a,double b){yes(Math.abs(a-b)<1e-5,a+" != "+b);}
 static UUID id(int n){return new UUID(0,n);}
 static void quotes(){BandwidthEngineTest.Graph g=new BandwidthEngineTest.Graph();UUID a=g.node(RADIO,1000),t=BandwidthEngineTest.terminal(g,a,1000),u=BandwidthEngineTest.terminal(g,a,1000),sw=BandwidthEngineTest.sw(g,t,1000),sw2=BandwidthEngineTest.sw(g,u,1000);UUID x=BandwidthEngineTest.server(g,sw,1000,1000,1000),y=BandwidthEngineTest.server(g,sw2,1000,1000,1000);BandwidthEngine engine=new BandwidthEngine(g.n,g.e);List<BandwidthEngine.Request> reserved=Collections.singletonList(new BandwidthEngine.Request("held",x,null,800,800));BandwidthEngine.Result base=engine.solve(reserved);NetworkAdmission.Quote q=new NetworkAdmission.Quote(engine,reserved,base);
  eq(engine.additional(base,Arrays.asList(x,y)),200);eq(q.additional(y,Collections.emptyMap()),200);Map<UUID,Integer> draft=new TreeMap<>();draft.put(y,201);yes(!q.failure(draft).isEmpty(),"reject shared antenna oversubscription");eq(q.project(draft).requests.get("held").served,800);eq(q.project(draft).requests.get("draft:"+y).served,200);draft.put(y,120);yes(q.failure(draft).isEmpty(),"candidate fits");eq(q.additional(x,draft),80);draft.put(x,80);yes(q.failure(draft).isEmpty(),"multi-host candidate fits");eq(q.additional(y,draft),0);draft.clear();eq(q.additional(y,draft),200);yes(q.failure(draft).isEmpty(),"empty draft");
  Random random=new Random(617);for(int i=0;i<500;i++){int held=random.nextInt(1001),ask=random.nextInt(1001);List<BandwidthEngine.Request> rr=Collections.singletonList(new BandwidthEngine.Request("held",x,null,held,held));BandwidthEngine.Result baseline=engine.solve(rr);NetworkAdmission.Quote quote=new NetworkAdmission.Quote(engine,rr,baseline);Map<UUID,Integer> want=Collections.singletonMap(y,ask);yes(quote.failure(want).isEmpty()==(held+ask<=1000),"admission protects reservations");eq(quote.additional(y,Collections.emptyMap()),1000-held);eq(quote.project(want).requests.get("held").served,held);}}
 static void tasks(){TaskEngine.Node a=FixedResourcesTest.node(100,0,FixedResourcesTest.POOL),b=FixedResourcesTest.node(101,1,FixedResourcesTest.POOL);TaskEngine.Task one=FixedResourcesTest.mining(1,a,0,0),two=FixedResourcesTest.mining(2,b,0,0);List<TaskEngine.Task> jobs=Arrays.asList(one,two);Set<Integer> local=new HashSet<>(Arrays.asList(1,2));BandwidthEngineTest.Graph g=new BandwidthEngineTest.Graph();UUID source=g.node(RADIO,8),terminal=BandwidthEngineTest.terminal(g,source,1000),s=BandwidthEngineTest.sw(g,terminal,1000),t=BandwidthEngineTest.sw(g,terminal,1000);g.n.add(new BandwidthEngine.Node(a.id,SERVER,1000,true));g.n.add(new BandwidthEngine.Node(b.id,SERVER,1000,true));g.edge(s,a.id,PATCH,1000);g.edge(t,b.id,PATCH,1000);BandwidthEngine engine=new BandwidthEngine(g.n,g.e);List<BandwidthEngine.Request> req=NetworkAdmission.requests(id(1),one.bindings,true);req.addAll(NetworkAdmission.requests(id(2),two.bindings,true));BandwidthEngine.Result result=engine.solve(req);yes(!NetworkAdmission.served(result,id(1),one.bindings)&&!NetworkAdmission.served(result,id(2),two.bindings),"fair shortfall is not a full reservation");TaskEngine.Plan p=FixedResources.plan(Arrays.asList(a,b),jobs,local,new int[]{1000,1000},Integer.MAX_VALUE,Collections.emptySet(),local);yes(p.tasks.get(1).work==0&&p.tasks.get(2).work==0,"no compute or earnings on insufficient WAN");yes(p.cpu[0]==1&&p.cpu[1]==1,"blocked jobs retain physical reservations");p=FixedResources.plan(Arrays.asList(a,b),jobs,local,new int[]{1000,1000},Integer.MAX_VALUE,Collections.emptySet(),Collections.singleton(2));yes(p.tasks.get(1).work>0&&p.tasks.get(2).work==0,"only served job executes");yes(FixedResources.hosts(one.bindings).equals(Collections.singleton(a.id)),"no hardware reassignment");}
 static void certificates(){PhysicalTopology t=new PhysicalTopology();PhysicalTopology.Pos a=new PhysicalTopology.Pos(0,0,0),f=new PhysicalTopology.Pos(1,0,0),g=new PhysicalTopology.Pos(2,0,0),f2=new PhysicalTopology.Pos(1,0,1),g2=new PhysicalTopology.Pos(2,0,1),wire=new PhysicalTopology.Pos(3,0,0),rack=new PhysicalTopology.Pos(4,0,0);PhysicalTopologyTest.put(t,a,PhysicalTopology.Kind.ANTENNA,PhysicalTopologyTest.d(1,RADIO,a,1000,null));PhysicalTopologyTest.put(t,f,PhysicalTopology.Kind.FIBER);PhysicalTopologyTest.put(t,g,PhysicalTopology.Kind.TERMINAL,PhysicalTopologyTest.d(2,TERMINAL,g,1000,null));PhysicalTopologyTest.put(t,wire,PhysicalTopology.Kind.DATA);PhysicalTopologyTest.put(t,rack,PhysicalTopology.Kind.RACK);yes(t.exclusiveFootprint(g,p->true).containsAll(Arrays.asList(a,f,g,wire,rack)),"full verified LAN and optical run");yes(t.exclusiveFootprint(g,p->!p.equals(f)).isEmpty(),"partial optical run cannot be certified");PhysicalTopologyTest.put(t,f2,PhysicalTopology.Kind.FIBER);PhysicalTopologyTest.put(t,g2,PhysicalTopology.Kind.TERMINAL,PhysicalTopologyTest.d(3,TERMINAL,g2,1000,null)); // adjacent terminals join LAN; move second farther away
  t.put(g2,null);g2=new PhysicalTopology.Pos(1,0,2);PhysicalTopologyTest.put(t,g2,PhysicalTopology.Kind.TERMINAL,PhysicalTopologyTest.d(3,TERMINAL,g2,1000,null));yes(t.exclusiveFootprint(g,p->true).isEmpty(),"shared antenna cannot be independently virtualized");}
 public static void main(String[] args){quotes();tasks();certificates();System.out.println("Network admission PASS: "+checks+" checks");}
}
